"""Dev-only fuzz harness: compare solver.py (C collector) against model.py."""
import json, random, subprocess, sys
sys.path.insert(0,'/workspace')
sys.path.insert(0,'/workspace/project')
import model as M
from request import load

def gen_case(rng):
    prim = rng.choice(['allreduce','reduce','broadcast','barrier','allgather','reducescatter'])
    mode = rng.choice([2,3])
    root = rng.randrange(4)
    if prim=='barrier':
        K,D = 1,0
    else:
        K = rng.randint(1,10)
        if prim=='reducescatter': K = 4*rng.randint(1,3)
        D = rng.randint(1,3)
    N = rng.randint(1,8)
    start = rng.choice([rng.randrange(0,2**24), rng.randrange(2**24-8,2**24)])
    trace = rng.randrange(0,5)
    events=[]
    K2=K
    for _ in range(rng.randint(0,25)):
        op = rng.choice(['data','data','ack','wire','budget','flush','retry','snap','train'])
        if op=='data':
            rank=rng.randrange(4); p=rng.randrange(K)
            ev={'op':'data','rank':rank,'p':p}
            if rng.random()<0.3:
                cnt=rng.randint(1,4); step=rng.choice([1,-1,0,2])
                if 0<=p+(cnt-1)*step<K: ev.update(count=cnt,step=step)
            if 'count' not in ev and rng.random()<0.4 and D>0:
                ev['values']=[rng.randrange(2**32) for _ in range(D)]
            if rng.random()<0.3:
                mx=57+4*D
                ev['xor']=[[rng.randint(0,mx),rng.randint(0,255)] for _ in range(rng.randint(1,3))]
            if rng.random()<0.3: ev['seed']=rng.randrange(2**32)
            events.append(ev)
        elif op=='ack':
            events.append({'op':'ack','rank':rng.randrange(4),'upto':rng.randint(0,3*K+1)})
        elif op=='wire':
            h=rng.randbytes(rng.randrange(0,80)).hex()
            events.append({'op':'wire','rank':rng.randrange(4),'hex':h})
        elif op=='budget':
            events.append({'op':'budget','n':rng.choice([-1,0,1,2,5])})
        elif op=='flush':
            events.append({'op':'flush'})
        elif op=='retry':
            events.append({'op':'retry','rank':rng.randrange(4)})
        elif op=='snap':
            events.append({'op':'snap','tag':'t%d'%rng.randrange(100)})
        elif op=='train':
            if K>=1:
                cnt=rng.randint(1,K); p=rng.randrange(K-cnt+1)
                events.append({'op':'train','p':p,'count':cnt,
                               'width':rng.randint(1,N),
                               'ranks':rng.sample(range(4),4),
                               'seed':rng.randrange(2**32),
                               **({'reverse':True} if rng.random()<0.3 else {})})
    return {'primitive':prim,'mode':mode,'root':root,'segments':K,'words':D,
            'capacity':N,'start':start,'events':events,'trace':trace}

def main():
    seed=int(sys.argv[1]) if len(sys.argv)>1 else 0
    rounds=int(sys.argv[2]) if len(sys.argv)>2 else 200
    rng=random.Random(seed)
    for it in range(rounds):
        cases=[gen_case(rng) for _ in range(rng.randint(1,3))]
        batch={'cases':cases}
        raw=json.dumps(batch,separators=(',',':')).encode()
        try:
            load(raw)
        except (ValueError,TypeError,KeyError,UnicodeError):
            continue
        p=subprocess.run(['python3','-I','-B','/workspace/project/solver.py'],
                         input=raw,capture_output=True)
        if p.returncode:
            print('CRASH at iter',it,p.stderr.decode()[:800]); return 1
        got=json.loads(p.stdout)
        exp={'cases':[M.run(c) for c in cases]}
        if got!=exp:
            print('MISMATCH at iter',it,'seed',seed)
            for i,(g,e) in enumerate(zip(got['cases'],exp['cases'])):
                if g!=e:
                    print('case',i,json.dumps(cases[i])[:2000])
                    for k in e:
                        if g.get(k)!=e[k]:
                            if k=='state':
                                print(' state diffs:',[(j,a,b) for j,(a,b) in enumerate(zip(g[k],e[k])) if a!=b])
                            elif k=='snapshots':
                                for si,(sg,se) in enumerate(zip(g[k],e[k])):
                                    if sg!=se:
                                        print(' snap',si,'tag',se['tag'])
                                        for sk in se:
                                            if sg.get(sk)!=se[sk]:
                                                if sk=='state':
                                                    print('   state diffs:',[(j,a,b) for j,(a,b) in enumerate(zip(sg[sk],se[sk])) if a!=b])
                                                else:
                                                    print('   ',sk,'got',str(sg.get(sk))[:120],'exp',str(se[sk])[:120])
                            elif k=='trace':
                                print(' trace lens',len(g[k]),len(e[k]))
                                for ti,(tg,te) in enumerate(zip(g[k],e[k])):
                                    if tg!=te:
                                        print('  trace',ti,'\n   got',tg['hex'][:160],'\n   exp',te['hex'][:160])
                                        break
                            else:
                                print(' ',k,'got',str(g.get(k))[:120],'exp',str(e[k])[:120])
                    break
            open('/workspace/tmp/fail_case.json','w').write(json.dumps(batch))
            return 1
        if it%50==0: print('ok',it,flush=True)
    print('all ok', rounds)
    return 0

sys.exit(main())
EOF
